cd /workspace/dev && python3 - <<'EOF'
import json, sys
sys.path.insert(0,'/workspace/dev')
import gen, harness, ref

def expected(req):
    try:
        for s in req['sessions']:
            ref.Ref(s)
    except AssertionError:
        return {'error': 'invalid'}
    return ref.run(req)

bad = tested = ill_count = 0
for seed in range(60):
    good = gen.gen_request(seed, sessions=2)['sessions']
    ill = gen.gen_request(1000+seed, sessions=1, illegal=True)['sessions']
    for combo in ([good[0], ill[0], good[1]], [ill[0], good[0]], [good[0], good[1], ill[0]]):
        req = {'version': 2, 'sessions': combo}
        want = expected(req)
        got, p = harness.run_request(req)
        tested += 1
        if want == {'error': 'invalid'}: ill_count += 1
        if got != want:
            bad += 1
            print('FAIL seed', seed, json.dumps(got)[:200], json.dumps(want)[:200])
            if bad > 3: break
print('tested=%d genuinely_illegal=%d failures=%d' % (tested, ill_count, bad))
EOF
